INSERT INTO `funds` (`id`, `name`, `mandate`, `share`, `status`, `created_at`) VALUES
('social', 'Social signal', 'Find products and companies whose organic customer enthusiasm or backlash is changing faster than the market has noticed: review sites (Amazon, app stores, Trustpilot, G2), TikTok, YouTube, Instagram, Facebook and X comments and transcripts, Reddit threads, podcasts and newsletters. Rising review velocity, viral demand, sold-out signals and sudden churn are the edge. Legacy media is late and consensus; weigh raw primary sources and quote the source URL for every claim acted on.', 0.25, 'active', '2026-09-01T00:00:00.000Z'),
('supply', 'Supply chain', 'Hunt for bottlenecks: shortages, allocation notices, rising lead times, freight and port congestion, single-source components, export controls, plant outages. Read 10-K risk factors and supplier concentration disclosures. Work out who captures pricing power from the bottleneck and who eats it, and trade the beneficiaries or exit the sufferers before it shows up in guidance. Legacy media is late and consensus; weigh raw primary sources and quote the source URL for every claim acted on.', 0.25, 'active', '2026-09-01T00:00:00.000Z'),
('catalyst', 'Catalyst run-ups', 'Trade the run-up into dated events: earnings dates and biotech FDA decisions (PDUFA dates, advisory committee meetings, topline readouts). Enter with a documented date and an exit before the event unless there is a stated reason to hold through it. Never guess a date; find it in a filing, an investor-relations page or the FDA calendar. Legacy media is late and consensus; weigh raw primary sources and quote the source URL for every claim acted on.', 0.25, 'active', '2026-09-01T00:00:00.000Z'),
('quant', 'Quant replication', 'Replicate what is documented to work at quant firms outside high-frequency trading: factor tilts (value, momentum, quality, low volatility), cross-sectional and time-series momentum, statistical arbitrage and pairs, mean reversion, post-earnings-announcement drift, event-driven and index-rebalance flows. Read the papers (arXiv q-fin, SSRN, AQR, Man AHL, Two Sigma, D. E. Shaw public research) and firm letters, implement the rule, backtest it with the backtest CLI or your own scripts, record the experiment, and only trade rules that survive out-of-sample. Prefer liquid names and crypto majors so the $ sizes here are tradable.', 0.25, 'active', '2026-09-01T00:00:00.000Z');
